import{_ as l,o as t,c as r,a8 as e}from"./chunks/framework.BWjTbCIc.js";const h=JSON.parse('{"title":"福建中学 · 2024–25资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"fukien","school_zh":"福建中学","school_en":"Fukien Secondary School","grade":"s1","year":"2024-25","year_label":"2024–25资料年份","type":"interview","title":"福建中学 · 2024–25资料年份 · 中一 · 面试","anonymous":true,"source_ids":["M192"],"rounds":["unknown","r1","r2"]},"headers":[],"relativePath":"reports/fukien/s1/2024-25-interview.md","filePath":"reports/fukien/s1/2024-25-interview.md"}'),i={name:"reports/fukien/s1/2024-25-interview.md"};function n(s,o,p,a,u,g){return t(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="福建中学-·-2024–25资料年份-·-中一-·-面试" tabindex="-1">福建中学 · 2024–25资料年份 · 中一 · 面试 <a class="header-anchor" href="#福建中学-·-2024–25资料年份-·-中一-·-面试" aria-label="Permalink to &quot;福建中学 · 2024–25资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/fukien">← 返回福建中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-m192" tabindex="-1">资料来源：福建中学中一入学面经2024-2025.pdf <a class="header-anchor" href="#record-m192" aria-label="Permalink to &quot;资料来源：福建中学中一入学面经2024-2025.pdf {#record-m192}&quot;">​</a></h2><p><strong>资料类型：</strong> 题目整理</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>面试安排</strong></p><p>資料整理者介紹，面試分為兩輪：</p><ul><li>第一輪為學生面試，時長約45分鐘。</li><li>第二輪為親子面試，時長約15分鐘。</li></ul><p>整理者列出的考察範圍包括：中、英文表達能力、邏輯推理能力、電腦應用能力、數學運算能力、應變能力、常識、體藝才能、學習態度及家庭支援。</p></blockquote><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>面试安排</strong></p><p>學生接受中文、英文及數學測試；由一名本地教師及一名外籍教師共同會見一名學生。</p></blockquote><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>朗讀與閱讀理解</strong></p><ul><li>朗讀文章後回答問題，例如：「文章的寫作手法／中心思想／主要內容是什麼？」</li><li>閱讀文言文《鄭人買履》，解釋指定字詞的含義。</li><li>從五篇文章中選一篇，回答：「覺得這篇寫得好在哪裡？」</li></ul><p><strong>個人情況與興趣問答</strong></p><p>材料列舉的問題包括：</p><ul><li>「你覺得自己像哪種動物，為什麼？」</li><li>「你會怎樣形容你的體育老師？」</li><li>「你平時最喜歡做什麼？有什麼興趣愛好？」</li><li>「有沒有參加過什麼課外活動或比賽？」</li><li>「你為什麼選擇福建中學？對我們學校有什麼瞭解？」</li><li>「你認為自己有什麼優點和缺點？可以舉例說明嗎？」</li><li>「你平時是怎麼學習的？有沒有自己的學習方法或計畫？」</li><li>「你最喜歡的科目是什麼？哪門科目你覺得最困難？為什麼？」</li></ul><p><strong>常識、時事與情境問答</strong></p><p>材料提及可能涉及以下問題：</p><ul><li>「三亞和香港的區別是什麼？」</li><li>「如果在學校裏和同學發生了矛盾，你會怎麼處理？」</li><li>「你對當前的一些時事熱點問題有什麼瞭解或看法，如香港的一些重大事件、社會現象等？」</li></ul><p><strong>詞語說故事</strong></p><p>用三個指定詞語說一個故事。材料提供的詞語示例為：「酒樓、祖先三代、其樂融融」。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗讀與問答</strong></p><p>用英文朗讀一篇文章並回答問題。整理者認為此環節主要考察詞彙量，並提醒考生注意朗讀流暢度。</p><p><strong>四格圖畫說故事</strong></p><p>閱讀四格英文圖畫，其中最後一格留白；考生須說出故事，並合理想像故事的結局。整理者將四格圖畫形容為香港考試中「最常見」的題型。</p><p>外籍教師會圍繞故事內容延伸討論。材料列出的問答示例為：</p><ul><li>“Do you like watching YouTube?”</li><li>“Do you think watching YouTube is good for study?”</li></ul><p><strong>日常生活問答</strong></p><p>材料介紹，問答一般圍繞學生日常生活展開，示例包括：</p><ul><li>“Which subject do you feel difficult?”</li><li>“Which one do you prefer to do after school, having dinner or doing homework?”</li></ul></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>电脑测试</strong></p><p>以電腦進行限時測試，完成數條數學題。</p><ul><li>題型包括計算題、應用題及圖形題。</li><li>部分題目要求說明解題思路。</li></ul></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 中文为主</p><p><strong>面试方式</strong></p><p>第二輪為親子面試，各家庭輪流進入課室與面試官見面。問題主要圍繞家長的教育理念展開。</p><p>整理者形容面試氣氛「非常輕鬆」，此為其對現場氛圍的評價。</p></blockquote><blockquote><p><strong>学生问答：</strong> 中文为主</p><p><strong>選校與中學生活</strong></p><ul><li>「你對福建中學有什麼期望？」</li><li>「你想在中學參加什麼課外活動？」</li><li>再次詢問選擇福建中學的原因；與首輪相比，可能要求更深入地闡述理由。</li></ul><p><strong>學習與未來規劃</strong></p><ul><li>「進入中學後有什麼學習計畫？如何提高自己的薄弱科目？」</li><li>「你長大後想從事什麼職業？為什麼會有這樣的想法？」</li></ul><p><strong>家庭與親子溝通</strong></p><ul><li>「你覺得你的家庭氛圍是怎樣的？家庭成員之間的相處方式對你有什麼影響？」</li><li>「平時你和父母是如何溝通交流的？遇到問題或想法時會怎麼和他們說？」</li></ul></blockquote><blockquote><p><strong>家长问答：</strong> 中文为主</p><p><strong>教育理念與家校配合</strong></p><ul><li>「您對孩子未來有什麼規劃？」</li><li>「您對孩子的教育理念是什麼？希望學校如何教育您的孩子？」</li><li>「您會如何配合學校對孩子進行教育？」</li><li>「平時會花多少時間陪伴孩子學習和成長？」</li></ul><p><strong>孩子的興趣與學習情況</strong></p><ul><li>「孩子有哪些興趣愛好？您是否有特意培養孩子某一方面的特長？」</li><li>「孩子在小學的學習情況如何？遇到困難時孩子是否尋求過家長的幫助？」</li></ul><p><strong>家庭互動與分工</strong></p><ul><li>「平時您和孩子是如何溝通交流的？孩子有什麼想法或感受會主動和您說嗎？」</li><li>「您的家庭氛圍是怎樣的？家庭成員之間的關係如何？」</li><li>「在孩子的教育過程中，您和配偶是如何分工合作的？」</li></ul></blockquote><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>整理者补充：</strong> 语言未注明</p><p><strong>整理者的准备建议</strong></p><p>资料整理者建议，除基础作答外，还应适当延伸想法，认为面试官希望听到有个人思考的回答。此为材料中的准备建议，不代表已确认的官方评分要求。</p></blockquote>',20)])])}const d=l(i,[["render",n]]);export{h as __pageData,d as default};
